#!/usr/bin/env bash
# Create runs/<run>/ in the upstream layout with a bundled checkpoint, so the diagnostics can load it.
# Usage: scripts/setup_run.sh egnn-dsm-smid0.01-seed0
# The endpoint data (data/LJ3Dwithsolute_{0,1}.00) are generated by upstream main.py on first use (MCMC).
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
RUN="$1"
UP="${NTI_UPSTREAM:-$ROOT/upstream/neuralTI-solvation}"
DEST="${NTI_RUNS:-$ROOT/runs}/$RUN"
mkdir -p "$DEST"
cp -r "$UP/src" "$UP/data" "$UP/experiments" "$DEST/"
cp "$ROOT/models/$RUN.model" "$DEST/experiments/LJsolute.model"
cp "$ROOT/models/$RUN.config.yaml" "$DEST/experiments/config.yaml"
echo "$DEST"
